/**
 * Returns the `n` value of each non-null item, upper-cased when the item's `a` equals 1.
 * @param {Array<{a: *, n: string} | null | undefined>} items
 * @returns {string[]}
 */
function proc(items) {
  return items
    .filter((item) => item != null)
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

/**
 * Splits a comma-separated string into trimmed, non-empty parts.
 * @param {string} text
 * @returns {string[]}
 */
function f2(text) {
  return text
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part !== '');
}

module.exports = { proc, f2 };

